module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButton,\n  EuiContextMenu,\n  EuiFormRow,\n  EuiIcon,\n  EuiPopover,\n  EuiSwitch,\n  EuiSpacer,\n} from '../../../../src/components';\n\nfunction flattenPanelTree(tree, array = []) {\n  array.push(tree);\n\n  if (tree.items) {\n    tree.items.forEach(item => {\n      if (item.panel) {\n        flattenPanelTree(item.panel, array);\n        item.panel = item.panel.id;\n      }\n    });\n  }\n\n  return array;\n}\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n\n    const panelTree = {\n      id: 0,\n      title: 'This is a context menu',\n      items: [\n        {\n          name: 'Handle an onClick',\n          icon: <EuiIcon type=\"search\" size=\"m\" />,\n          onClick: () => {\n            this.closePopover();\n            window.alert('Show fullscreen');\n          },\n        },\n        {\n          name: 'Go to a link',\n          icon: 'user',\n          href: 'http://elastic.co',\n          target: '_blank',\n        },\n        {\n          name: 'Nest panels',\n          icon: 'user',\n          panel: {\n            id: 1,\n            title: 'Nest panels',\n            items: [\n              {\n                name: 'PDF reports',\n                icon: 'user',\n                onClick: () => {\n                  this.closePopover();\n                  window.alert('PDF reports');\n                },\n              },\n              {\n                name: 'Embed code',\n                icon: 'user',\n                panel: {\n                  id: 2,\n                  title: 'Embed code',\n                  content: (\n                    <div style={{ padding: 16 }}>\n                      <EuiFormRow label=\"Generate a public snapshot?\">\n                        <EuiSwitch\n                          name=\"switch\"\n                          id=\"asdf\"\n                          label=\"Snapshot data\"\n                        />\n                      </EuiFormRow>\n                      <EuiFormRow label=\"Include the following in the embed\">\n                        <EuiSwitch\n                          name=\"switch\"\n                          id=\"asdf2\"\n                          label=\"Current time range\"\n                        />\n                      </EuiFormRow>\n                      <EuiSpacer />\n                      <EuiButton fill>Copy iFrame code</EuiButton>\n                    </div>\n                  ),\n                },\n              },\n              {\n                name: 'Permalinks',\n                icon: 'user',\n                onClick: () => {\n                  this.closePopover();\n                  window.alert('Permalinks');\n                },\n              },\n            ],\n          },\n        },\n        {\n          name: 'You can add a tooltip',\n          icon: 'user',\n          toolTipTitle: 'Optional tooltip',\n          toolTipContent: 'Optional content for a tooltip',\n          toolTipPosition: 'right',\n          onClick: () => {\n            this.closePopover();\n            window.alert('Display options');\n          },\n        },\n        {\n          name: 'Disabled option',\n          icon: 'user',\n          toolTipContent: 'For reasons, this item is disabled',\n          toolTipPosition: 'right',\n          disabled: true,\n          onClick: () => {\n            this.closePopover();\n            window.alert('Disabled option');\n          },\n        },\n      ],\n    };\n\n    this.panels = flattenPanelTree(panelTree);\n  }\n\n  onButtonClick = () => {\n    this.setState(prevState => ({\n      isPopoverOpen: !prevState.isPopoverOpen,\n    }));\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  render() {\n    const button = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick}>\n        Click me to load a context menu\n      </EuiButton>\n    );\n\n    return (\n      <EuiPopover\n        id=\"contextMenu\"\n        button={button}\n        isOpen={this.state.isPopoverOpen}\n        closePopover={this.closePopover}\n        panelPaddingSize=\"none\"\n        withTitle\n        anchorPosition=\"downLeft\">\n        <EuiContextMenu initialPanelId={0} panels={this.panels} />\n      </EuiPopover>\n    );\n  }\n}\n"