module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButtonEmpty,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiSuggest,\n  EuiSuperDatePicker,\n} from '../../../../src/components';\n\nimport { GlobalFilterBar } from './global_filter_bar';\nimport GlobalFilterOptions from './global_filter_options';\nimport HashtagPopover from './hashtag_popover';\n\nconst shortDescription = 'This is the description';\n\nconst sampleItems = [\n  {\n    type: { iconType: 'kqlField', color: 'tint4' },\n    label: 'Field sample',\n    description: shortDescription,\n  },\n  {\n    type: { iconType: 'kqlValue', color: 'tint0' },\n    label: 'Value sample',\n    description: shortDescription,\n  },\n  {\n    type: { iconType: 'kqlSelector', color: 'tint2' },\n    label: 'Conjunction sample',\n    description: shortDescription,\n  },\n  {\n    type: { iconType: 'kqlOperand', color: 'tint1' },\n    label: 'Operator sample',\n    description: shortDescription,\n  },\n  {\n    type: { iconType: 'search', color: 'tint8' },\n    label: 'Recent search',\n  },\n  {\n    type: { iconType: 'save', color: 'tint3' },\n    label: 'Saved search',\n  },\n];\n\nexport default class extends Component {\n  state = {\n    status: 'unchanged',\n    value: '',\n    hideDatepicker: false,\n    filters: [\n      {\n        id: 'filter0',\n        field: '@tags.keyword',\n        operator: 'IS',\n        value: 'value',\n        isDisabled: false,\n        isPinned: true,\n        isExcluded: false,\n      },\n      {\n        id: 'filter1',\n        field: '@tags.keyword',\n        operator: 'IS',\n        value: 'value',\n        isDisabled: true,\n        isPinned: false,\n        isExcluded: false,\n      },\n      {\n        id: 'filter2',\n        field: '@tags.keyword',\n        operator: 'IS NOT',\n        value: 'value',\n        isDisabled: false,\n        isPinned: true,\n        isExcluded: true,\n      },\n      {\n        id: 'filter3',\n        field: '@tags.keyword',\n        operator: 'IS',\n        value: 'value',\n        isDisabled: false,\n        isPinned: false,\n        isExcluded: false,\n      },\n    ],\n  };\n\n  onFieldFocus = () => {\n    this.setState({\n      hideDatepicker: true,\n    });\n  };\n\n  onFieldBlur = () => {\n    this.setState({\n      hideDatepicker: false,\n    });\n  };\n\n  getInputValue = val => {\n    this.setState({\n      value: val,\n    });\n  };\n\n  onItemClick = item => {\n    alert(`Item [${item.label}] was clicked`);\n  };\n\n  onTimeChange() {\n    alert('Time changed');\n  }\n\n  render() {\n    const append = <EuiButtonEmpty>KQL</EuiButtonEmpty>;\n\n    return (\n      <div className=\"savedQueriesInput\">\n        <EuiFlexGroup\n          gutterSize=\"s\"\n          className={\n            this.state.hideDatepicker ? 'savedQueriesInput__hideDatepicker' : ''\n          }>\n          <EuiFlexItem>\n            <EuiSuggest\n              status={this.state.status}\n              onFocus={this.onFieldFocus}\n              onBlur={this.onFieldBlur}\n              prepend={<HashtagPopover value={this.state.value} />}\n              append={append}\n              suggestions={sampleItems}\n              onItemClick={this.onItemClick}\n              onInputChange={this.getInputValue}\n            />\n          </EuiFlexItem>\n          <EuiFlexItem grow={false} className=\"savedQueriesInput__datepicker\">\n            <EuiSuperDatePicker onTimeChange={this.onTimeChange} />\n          </EuiFlexItem>\n        </EuiFlexGroup>\n        <EuiFlexGroup\n          className=\"globalFilterGroup\"\n          gutterSize=\"none\"\n          alignItems=\"flexStart\"\n          responsive={false}>\n          <EuiFlexItem className=\"globalFilterGroup__branch\" grow={false}>\n            <GlobalFilterOptions />\n          </EuiFlexItem>\n          <EuiFlexItem className=\"globalFilterGroup__filterFlexItem\">\n            <GlobalFilterBar\n              className=\"globalFilterGroup__filterBar\"\n              filters={this.state.filters}\n            />\n          </EuiFlexItem>\n        </EuiFlexGroup>\n      </div>\n    );\n  }\n}\n"