module.exports = "// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n\n// This example JS is overly complex for simple icon usage\n// and is set up this way for ease of use in our docs.\n//\n// Check the snippet tab for a more common usage.\n\nimport React from 'react';\n\nimport {\n  EuiFlexGrid,\n  EuiFlexItem,\n  EuiIcon,\n  EuiPanel,\n  EuiText,\n  EuiCopy,\n} from '../../../../src/components';\n\nconst iconTypes = [\n  'logoAerospike',\n  'logoApache',\n  'logoAWS',\n  'logoAWSMono',\n  'logoAzure',\n  'logoAzureMono',\n  'logoCeph',\n  'logoCodesandbox',\n  'logoCouchbase',\n  'logoDocker',\n  'logoDropwizard',\n  'logoEtcd',\n  'logoGCP',\n  'logoGCPMono',\n  'logoGithub',\n  'logoGmail',\n  'logoGolang',\n  'logoHAproxy',\n  'logoIBM',\n  'logoIBMMono',\n  'logoKafka',\n  'logoKubernetes',\n  'logoMemcached',\n  'logoMongodb',\n  'logoMySQL',\n  'logoNginx',\n  'logoOsquery',\n  'logoPhp',\n  'logoPostgres',\n  'logoPrometheus',\n  'logoRabbitmq',\n  'logoRedis',\n  'logoSketch',\n  'logoSlack',\n  'logoWebhook',\n  'logoWindows',\n].sort();\n\nexport default () => (\n  <EuiFlexGrid columns={4}>\n    {iconTypes.map(iconType => (\n      <EuiFlexItem\n        className=\"guideDemo__icon\"\n        key={iconType}\n        style={{ width: '200px' }}>\n        <EuiCopy textToCopy={iconType} afterMessage={`${iconType} copied`}>\n          {copy => (\n            <EuiPanel onClick={copy} className=\"eui-textCenter\">\n              <EuiIcon type={iconType} size=\"xl\" />\n              <EuiText size=\"s\">\n                <p>{iconType}</p>\n              </EuiText>\n            </EuiPanel>\n          )}\n        </EuiCopy>\n      </EuiFlexItem>\n    ))}\n  </EuiFlexGrid>\n);\n"