module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButton,\n  EuiButtonEmpty,\n  EuiButtonIcon,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiButtonToggle,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      toggle0On: false,\n    };\n  }\n\n  onToggle0Change = e => {\n    this.setState({ toggle0On: e.target.checked });\n  };\n\n  render() {\n    return (\n      <EuiFlexGroup\n        wrap\n        gutterSize=\"s\"\n        alignItems=\"center\"\n        className=\"guideDemo__ghostBackground\">\n        <EuiFlexItem grow={false}>\n          <EuiButton\n            color=\"ghost\"\n            onClick={() => window.alert('Button clicked')}>\n            Primary\n          </EuiButton>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiButton\n            fill\n            color=\"ghost\"\n            size=\"s\"\n            iconType=\"check\"\n            onClick={() => window.alert('Button clicked')}>\n            Filled\n          </EuiButton>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiButtonEmpty\n            size=\"s\"\n            color=\"ghost\"\n            onClick={() => window.alert('Button clicked')}>\n            small\n          </EuiButtonEmpty>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiButtonIcon\n            size=\"s\"\n            color=\"ghost\"\n            iconType=\"user\"\n            onClick={() => window.alert('Button clicked')}\n            aria-label=\"Your account\"\n          />\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiButton color=\"ghost\" isLoading fill size=\"s\">\n            Loading&hellip;\n          </EuiButton>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiButton color=\"ghost\" isLoading>\n            Loading&hellip;\n          </EuiButton>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiButtonToggle\n            color=\"ghost\"\n            label=\"Toggle Me\"\n            fill={this.state.toggle0On}\n            onChange={this.onToggle0Change}\n          />\n        </EuiFlexItem>\n      </EuiFlexGroup>\n    );\n  }\n}\n"